export function Hero({
  heading = "{{heading}}",
  subheading = "{{subheading}}",
  align = "{{align}}",
  accent = "{{accent}}",
  cta = {{cta}},
}) {
  const centered = align === "center";
  return (
    <section style={{
      fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", padding: "36px 24px",
      display: "flex", flexDirection: "column", alignItems: centered ? "center" : "flex-start",
      textAlign: centered ? "center" : "left", background: `linear-gradient(135deg, ${accent}, #FAF7F2)`,
    }}>
      <h1 style={{ margin: "0 0 10px", fontSize: 26, fontWeight: 700, maxWidth: "26ch" }}>{heading}</h1>
      <p style={{ margin: "0 0 18px", maxWidth: "42ch", color: "#241430cc" }}>{subheading}</p>
      {cta && (
        <button type="button" style={{ background: "#241430", color: "#FAF7F2", border: "none", padding: "10px 20px", borderRadius: 999, fontWeight: 600, fontSize: 14, cursor: "pointer" }}>
          Get started
        </button>
      )}
    </section>
  );
}
